import {createDesmosGuide,desmosQuestionButton} from './desmos-ui.js?v=10';
import {LESSONS,VOCAB,ROOTS,CHALLENGE,CURRICULUM_REFERENCES} from './learning-content.js?v=10';
import {calculate} from './logic.js?v=10';
import {localDate,addDays,rankSkills,buildPlan,validDate} from './planner.js?v=10';
import {initializeStudio,award,activity,reviewQueue,recordReview,rateVocabulary,examTaken,createExam,remainingSeconds,submitExamModule,startNextModule,finishExam,isIndependent} from './studio-logic.js?v=10';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=date=>new Date(date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
const button=(label,action,extra='',primary=false)=>`<button class="${primary?'primary':'secondary'}" data-action="${action}" ${extra}>${label}</button>`;
const percent=(n,total)=>total?Math.round(n/total*100)+'%':'—';
const heading=(title,description)=>`<div class="page-title"><div><h1>${title}</h1><p>${description}</p></div></div>`;
const source=q=>`<details class="source"><summary>Official source · ${esc(q.file)} · page ${q.page}</summary><p>Question ${esc(q.number)} · ID ${esc(q.id)}</p></details>`;
const normalize=text=>String(text).trim().toLowerCase().replace(/[.!?]+$/,'').replace(/\s+/g,' ');
export function createStudio(context){
 const {getState,getData,getProfile,save,render,toast,startPractice,history}=context;
 const state=()=>getState(),data=()=>getData(),settings=()=>initializeStudio(state());
 const allRecords=()=>state().sessions.filter(s=>s.section===state().section).flatMap(s=>s.records);
 const ranks=()=>rankSkills({section:state().section,diagnostics:state().diagnostics,sessions:state().sessions,questions:data().questions});
 const taken=()=>examTaken(state(),history());
 const bank=()=>new Map(data().questions.map(q=>[q.id,q]));
 const modal=()=>document.querySelector('#modal');
 let lessonId=null,lessonFeedback='',lessonAttempts=0,lessonExposed=false,vocabMode='cards',vocabIndex=0,flipped=false,query='',reviewId=null,reviewFeedback=null,graphInput='x^2-4',graphRange=10,highlightMode=false;
 const desmos=createDesmosGuide({getState:state,save,getData:data,getQuestionText:id=>context.questionText?.(id)||'',openTool,onUse:(questionId,tipId)=>{if(context.onDesmosTip?.(questionId,tipId))return true;if(location.hash==='#review'&&reviewId===questionId&&!reviewFeedback){const box=document.querySelector('#review-form input[name=hinted]');if(box){box.checked=true;return true;}}return false;}});
 function applyTheme(){document.body.dataset.theme=settings().theme;document.body.classList.toggle('focus-mode',settings().focus);}
 function freshSkill(skill,count=5){const available=data().questions.filter(q=>q.section===state().section&&q.skill===skill&&!taken().has(q.id));const stable=ranks().find(r=>r.skill===skill)?.stable&&context.canHard();return available.filter(q=>stable||q.difficulty!=='Hard').sort((a,b)=>Number(b.difficulty===(stable?'Hard':'Medium'))-Number(a.difficulty===(stable?'Hard':'Medium'))).slice(0,count).map(q=>q.id);}
 function practiceSkill(skill){const ids=freshSkill(skill);if(!ids.length){openTool('Load questions for this skill',`<p>No fresh ${esc(skill)} questions are available in your library. Lessons and vocabulary remain available.</p><p>Import more questions locally, then return here. Repeated questions stay in Review and do not count as fresh checks.</p><a class="primary" href="setup.html">Load a question library</a> <a class="secondary" href="#lessons" data-action="close-modal">Browse lessons</a>`);return;}startPractice(ids,'lesson');}
 function recommended(){const ordered=ranks().map(r=>LESSONS.find(l=>l.section===state().section&&l.skill===r.skill)).filter(Boolean);return ordered.filter(l=>!settings().lessons[l.id]?.completed).concat(ordered.filter(l=>settings().lessons[l.id]?.completed)).slice(0,3);}
 function calendar(){const stats=activity(state()),today=localDate(),first=today.slice(0,8)+'01',days=new Date(Number(today.slice(0,4)),Number(today.slice(5,7)),0).getDate(),offset=new Date(first+'T12:00:00Z').getUTCDay();return `<div class="calendar-grid" aria-label="Study activity this month">${['S','M','T','W','T','F','S'].map(d=>`<span class="small muted">${d}</span>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const date=first.slice(0,8)+String(i+1).padStart(2,'0');return `<span class="calendar-day ${stats.dates.has(date)?'studied':''} ${date===today?'today':''}" title="${date}: ${stats.dates.get(date)||0} XP">${i+1}</span>`;}).join('')}</div>`;}
 function lessonCard(l){const completed=settings().lessons[l.id]?.completed;return `<article class="lesson-card"><small>${esc(l.skill)} · ${l.minutes} min</small><h3>${esc(l.title)}</h3><p>${esc(l.intro)}</p><footer><span class="pill">${completed?'Reviewed':'Guided lesson'}</span>${button(completed?'Revisit':'Open lesson','lesson-open',`data-id="${l.id}"`)}</footer></article>`;}
 function dashboard(){
  const stats=activity(state()),today=localDate(),queue=reviews().filter(r=>r.due&&r.question.section===state().section);
  let days=[];try{if(state().routine)days=buildPlan({routine:state().routine,diagnostics:state().diagnostics,sessions:state().sessions,questions:data().questions,history:[...history(),...[...taken()].map(questionId=>({questionId}))]}).days.filter(d=>d.date>=today&&d.section===state().section).slice(0,5);}catch{}
  if(!days.length)days=Array.from({length:4},(_,i)=>({date:addDays(today,i),skills:[ranks()[i%ranks().length]?.skill||'Foundation'],section:state().section}));
  const skill=days[0]?.skills?.[0],lesson=LESSONS.find(l=>l.section===state().section&&l.skill===skill)||recommended()[0];
  const learned=!!settings().lessons[lesson?.id]?.completed;
  const practiced=state().sessions.some(s=>s.section===state().section&&s.type!=='assessment'&&s.completed&&s.completedAt&&localDate(new Date(s.completedAt))===today);
  const paused=state().sessions.find(s=>s.id===state().activeId&&s.section===state().section&&s.type!=='assessment'&&!s.completed)||state().sessions.find(s=>s.section===state().section&&s.type!=='assessment'&&!s.completed);
  const skillAvailable=lesson?freshSkill(lesson.skill).length:0;
  const practiceAction=paused?button('Resume set','resume',`data-id="${paused.id}"`,learned&&!practiced):lesson&&skillAvailable?button(practiced?'More practice':'Start practice','lesson-practice',`data-skill="${esc(lesson.skill)}"`,learned&&!practiced):'<a class="secondary" href="setup.html">Load practice questions</a>';
  return `<section class="learn-heading"><h1>Learn</h1><p>${esc(state().section)} · ${short(today)}</p></section><div class="learn-layout"><section class="daily-path"><div class="daily-path-head"><div><h2>Today’s path</h2><p>${esc(lesson?.skill||'Build your foundation')}</p></div><a class="text-button" href="#plan">Edit routine</a></div><ol class="daily-steps"><li class="daily-step ${learned?'done':'current'}"><span class="daily-step-number">${learned?'✓':'1'}</span><div class="daily-step-copy"><small>Lesson · ${lesson?.minutes||5} min</small><h3>${esc(lesson?.title||'Start with a lesson')}</h3><p>${learned?'You’ve reviewed this lesson. Revisit it anytime.':'Learn the method with one worked example.'}</p></div>${lesson?button(learned?'Revisit':'Start lesson','lesson-open',`data-id="${lesson.id}"`,!learned):'<a class="primary" href="#lessons">Browse lessons</a>'}</li><li class="daily-step ${practiced?'done':learned?'current':''}"><span class="daily-step-number">${practiced?'✓':'2'}</span><div class="daily-step-copy"><small>Practice · ${paused?paused.questionIds.length-paused.records.length+' left':skillAvailable?Math.min(5,skillAvailable)+' questions':'Library needed'}</small><h3>${paused?'Continue your set':skillAvailable?'Put the method to work':'Add your question library'}</h3><p>${paused?'Your answers and setup are saved.':skillAvailable?'Fresh questions, one at a time.':'No official questions are bundled. Import your own collection for practice and fresh checks.'}</p></div>${practiceAction}</li><li class="daily-step ${queue.length?'':'done'}"><span class="daily-step-number">${queue.length?'3':'✓'}</span><div class="daily-step-copy"><small>Review · ${queue.length} due</small><h3>${queue.length?'Make the correction stick':'You’re caught up'}</h3><p>${queue.length?'Rework missed or hinted questions.':'Your next review will appear here.'}</p></div><a class="secondary" href="#review">${queue.length?'Review mistakes':'View saved questions'}</a></li></ol>${context.retentionPanel?.()||''}<details class="upcoming-path"><summary>Coming up next</summary><ol>${days.slice(1,4).map(d=>`<li><span>${short(d.date)}</span><strong>${esc(d.skills?.[0]||'Practice and review')}</strong></li>`).join('')}</ol><a class="text-button" href="#plan">Full study plan</a></details></section><aside class="learn-sidebar"><section class="rhythm-compact"><div class="rhythm-stats"><div><strong>${stats.streak}</strong><small>day streak</small></div><div><strong>${stats.weekXp}<span> / ${settings().weeklyGoal}</span></strong><small>weekly XP</small></div></div><div class="mastery-track"><span style="width:${Math.min(100,stats.weekXp/settings().weeklyGoal*100)}%"></span></div><details class="activity-details"><summary>Study activity</summary>${calendar()}<p class="small muted">XP measures effort, not your SAT score.</p></details></section><div class="next-review"><h3>Your focus</h3><p>${esc(lesson?.skill||'Foundation skills')}</p><a class="text-button" href="#analytics">See skill progress</a></div><div class="learn-shortcuts"><a href="#lessons">All lessons</a><a href="#desmos">Desmos tips</a><a href="#achievements">Milestones</a></div></aside></div>`;
 }
 function lessons(){
  const l=LESSONS.find(l=>l.id===lessonId&&l.section===state().section);
  if(l)return heading(esc(l.title),esc(l.skill)+' · '+l.minutes+' minute lesson')+`<article class="lesson-detail studio-panel"><div class="studio-toolbar">${button('All lessons','lessons-back')}<span class="pill">Original tutorial example</span></div><p>${esc(l.intro)}</p><ol class="lesson-steps">${l.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><section class="lesson-worked"><h2>Work through an example</h2><p>${esc(l.worked.prompt)}</p><p class="equation">${esc(l.worked.setup)}</p><p>${esc(l.worked.solution)}</p><p><strong>Trap:</strong> ${esc(l.worked.trap)}</p></section><div class="recognition"><strong>Recognition rule</strong><p>${esc(l.rule)}</p></div>${l.desmos?`<p><strong>Desmos:</strong> ${esc(l.desmos)} <a href="https://www.desmos.com/calculator" target="_blank" rel="noopener noreferrer">Open calculator</a></p>`:''}${l.prerequisites?.length?`<p class="small muted">Useful foundations: ${l.prerequisites.map(id=>LESSONS.find(x=>x.id===id)?.title).filter(Boolean).map(esc).join(', ')}.</p>`:''}<section><h2>Check your understanding</h2><p>${esc(l.check.prompt)}</p><form id="lesson-check-form"><label for="lesson-check-answer">Your answer</label><input id="lesson-check-answer" name="answer" type="text" required autocomplete="off"><button class="primary" type="submit">Check understanding</button></form>${lessonFeedback?`<div class="feedback" role="status">${lessonFeedback}</div>`:''}</section><div class="summary-actions">${context.returnToPath?.()||button('Practice this skill','lesson-practice',`data-skill="${esc(l.skill)}"`,true)}<a class="secondary" href="#review">Review earlier mistakes</a>${l.section==='Math'?button('Desmos methods for this skill','desmos-skill',`data-skill="${esc(l.skill)}"`):''}</div><p class="source-label">This lesson and its examples are authored study material. Official practice questions keep their PDF citations.</p></article>`;
  return heading('Lessons','Choose a skill to learn or revisit.')+`<details class="lesson-scope"><summary>Coverage and official course references</summary><p>111 original lessons cover the 29 question-bank skills, with focused follow-ups in both sections. These lessons are independent study material; completing them does not certify mastery.</p><p><a href="https://www.khanacademy.org/sat-math" target="_blank" rel="noopener noreferrer">Khan Academy SAT Math</a> · <a href="https://www.khanacademy.org/sat-reading-and-writing" target="_blank" rel="noopener noreferrer">Khan Academy Reading and Writing</a> · <a href="https://satsuite.collegeboard.org/practice/khan-academy" target="_blank" rel="noopener noreferrer">College Board course guidance</a></p></details>`+`<div class="studio-toolbar"><label>Search lessons<input id="lesson-search" type="search" placeholder="Skill or lesson title" value="${esc(query)}"></label><span class="pill">${LESSONS.filter(l=>l.section===state().section).length} lessons in this section</span></div><div class="lesson-catalog">${LESSONS.filter(l=>l.section===state().section&&[l.title,l.skill].join(' ').toLowerCase().includes(query.toLowerCase())).map(lessonCard).join('')}</div>`;
 }
 function reviews(){const old=history().filter(r=>!r.correct||r.assistance==='hinted').map(r=>({...r,hintsUsed:r.assistance==='hinted'?1:0,setupCorrect:null,exactSkill:r.skill}));return reviewQueue({...state(),sessions:[{records:old},...state().sessions]},data().questions);}
 function review(){
  const list=reviews().filter(r=>r.question.section===state().section),item=list.find(r=>r.question.id===reviewId);
  if(item){const q=item.question,r=item.record,feedback=reviewFeedback;return heading('Repair the reasoning. Keep the rule.',esc(q.skill)+' · '+item.reason)+`<section class="review-card studio-panel">${button('Back to queue','review-back')}${desmosQuestionButton(q)}<p class="small muted">Intentional review of an attempted question. This is tracked separately from fresh practice.</p><img class="bank-image" src="${q.image}" alt="Official question ${esc(q.id)}"><p><strong>Earlier answer:</strong> ${esc(r.answer||'Not recorded')} · ${r.correct?'Correct':'Incorrect or revealed'}</p>${r.setup?`<p><strong>Earlier setup:</strong> ${esc(r.setup)}</p>`:''}<form id="review-form"><label>Your corrected answer<input name="answer" type="text" required></label><label>Your corrected setup or reasoning<textarea name="setup" required>${esc(item.progress?.setup||'')}</textarea></label><label>What went wrong?<select name="errorType">${['Translation / model','Requested quantity','Concept / rule','Algebra / arithmetic','Evidence / meaning','Pacing','Unknown'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>A rule you can recognize next time<textarea name="rule" required>${esc(item.progress?.rule||'')}</textarea></label><label class="quantity-check"><input name="hinted" type="checkbox"><span>I used help or looked at the answer during this review.</span></label><button class="primary" type="submit">Check and schedule review</button></form>${feedback?`<div class="feedback" role="status"><h3>${feedback.correct?'Correct rework.':'Review this approach again.'}</h3><p>Answer: ${esc(q.answer)}. Next review: ${short(feedback.next.due)}. Review accuracy is kept separate from new unassisted answers.</p>${q.key?.rationale?`<p>${esc(q.key.rationale)}</p>`:''}${q.key?`<a href="${esc(q.key.url)}" target="_blank" rel="noopener noreferrer">Official worked solution</a>`:'<p>A detailed official worked solution is not available in this collection for this item.</p>'}</div>`:''}<div class="summary-actions">${context.returnToPath?.()||''}${button('Try a fresh question','review-fresh',`data-skill="${esc(q.skill)}"`)}${button('Study the skill','review-lesson',`data-skill="${esc(q.skill)}"`)}</div>${source(q)}</section>`;}
  return heading('Review','Correct earlier mistakes, then test the skill on fresh questions after a gap.')+(context.retentionPanel?.()||'')+`<div class="studio-stats"><div class="studio-stat"><strong>${list.filter(r=>r.due).length}</strong><small>Reviews due</small></div><div class="studio-stat"><strong>${list.filter(r=>r.progress?.successes).length}</strong><small>Successfully reworked</small></div><div class="studio-stat"><strong>${settings().saved.length}</strong><small>Saved questions</small></div></div>${list.length?list.map(item=>`<article class="review-card studio-panel"><div class="studio-section-head"><div><small>${esc(item.question.file)} · p. ${item.question.page} · Q ${esc(item.question.number)} · ID ${item.question.id}</small><h3>${esc(item.question.skill)}</h3></div><span class="pill">${item.due?'Due now':'Due '+short(item.progress.due)}</span></div><div class="review-tags"><span>${item.reason}</span>${item.progress?.errorType?`<span>${esc(item.progress.errorType)}</span>`:''}</div>${item.progress?.rule?`<p class="review-note">${esc(item.progress.rule)}</p>`:''}${button('Rework question','review-open',`data-id="${item.question.id}"`)}</article>`).join(''):'<div class="studio-empty"><h2>Your queue is clear.</h2><p>Missed, hinted, revealed, and saved questions appear here after practice.</p><a class="primary" href="#practice">Start practicing</a></div>'}`;
 }
 function analytics(){
  const records=allRecords(),list=ranks(),counts={strong:list.filter(r=>r.stable).length,focus:list.filter(r=>!r.stable&&(r.practiceCount||r.diagnosticCount)).length,unstarted:list.filter(r=>!r.practiceCount&&!r.diagnosticCount).length};
  const stats=activity(state()),points=Array.from({length:14},(_,i)=>{const date=addDays(localDate(),i-13);return {date,xp:stats.dates.get(date)||0};}),max=Math.max(30,...points.map(x=>x.xp));
  return heading('Analysis','Your strengths, focus areas, and score checkpoints.')+(context.calibrationPanel?.()||'')+`<div class="studio-stats"><div class="studio-stat"><strong>${percent(records.filter(r=>r.correct).length,records.length)}</strong><small>Practice answer accuracy</small></div><div class="studio-stat"><strong>${counts.strong}</strong><small>Stable skills</small></div><div class="studio-stat"><strong>${counts.focus}</strong><small>Focus areas</small></div><div class="studio-stat"><strong>${counts.unstarted}</strong><small>Not assessed yet</small></div></div><div class="studio-grid"><section class="studio-panel"><h2>Practice rhythm</h2><div class="activity-chart"><svg role="img" aria-label="Study XP across the last fourteen days" viewBox="0 0 560 150">${points.map((p,i)=>`<rect x="${i*40+3}" y="${130-p.xp/max*115}" width="25" height="${Math.max(2,p.xp/max*115)}" rx="4" fill="var(--teal)"><title>${p.date}: ${p.xp} XP</title></rect>`).join('')}<text x="0" y="147" fill="currentColor" font-size="11">${short(points[0].date)}</text><text x="495" y="147" fill="currentColor" font-size="11">Today</text></svg></div><p class="small muted">Activity measures effort. A stable skill needs at least five recent attempts and 80% independent, correct answers with a valid approach.</p></section><section class="studio-panel"><h2>Official score checkpoints</h2><p>Record a Bluebook or official test score to compare with your goal. Practice accuracy is not converted into a predicted SAT score.</p>${button('Add score report','score-add')}<div>${settings().scoreReports.map(r=>`<p><strong>${r.math+r.readingWriting}</strong> · ${short(r.date)} · ${esc(r.label)}<small> Math ${r.math} / R&amp;W ${r.readingWriting}</small></p>`).join('')||'<p class="small muted">No score checkpoints added yet.</p>'}</div></section></div><div class="studio-section-head"><h2>Skills to work on next</h2><a href="#progress">Exact attempt history</a></div><div class="skill-grid">${list.map(r=>`<article class="skill-tile"><span class="pill">${r.stable?'Stable':r.practiceCount||r.diagnosticCount?'Focus':'Not assessed'}</span><h3>${esc(r.skill)}</h3><p>${esc(r.reason)}</p><div class="mastery-track"><span style="width:${r.practiceCount?100*r.independent/r.practiceCount:0}%"></span></div><p class="small muted">${r.independent}/${r.practiceCount} recent approaches independently correct</p>${button('Study skill','review-lesson',`data-skill="${esc(r.skill)}"`)}</article>`).join('')}</div>`;
 }
 function vocabulary(){
  const due=VOCAB.filter(w=>!settings().vocab[w.id]?.due||settings().vocab[w.id].due<=localDate()),deck=due.length?due:VOCAB,w=deck[vocabIndex%deck.length];
  const tabs=`<div class="studio-segment" role="tablist" aria-label="Vocabulary view">${[['cards','Review cards'],['words','Words'],['roots','Roots'],['saved','Saved']].map(([id,name])=>`<button role="tab" aria-selected="${vocabMode===id}" data-action="vocab-tab" data-mode="${id}">${name}</button>`).join('')}</div>`;
  if(vocabMode==='cards')return heading('Vocabulary','Recall the meaning, then flip the card.')+tabs+`<div class="vocab-layout"><section><p class="small muted">${due.length} of ${VOCAB.length} words due today${due.length?'':'; browsing completed cards is optional'}.</p><button class="flashcard" data-action="vocab-flip" aria-label="${flipped?'Show word':'Reveal definition for '+esc(w.word)}"><span class="word">${esc(w.word)}</span><span class="part">${esc(w.part)}</span>${flipped?`<span class="definition">${esc(w.definition)}</span><span class="example">${esc(w.example)}</span>${w.root?`<span class="vocab-root">${esc(w.root)}</span>`:''}`:'<span class="small muted">Think of a meaning, then tap to reveal.</span>'}</button><div class="vocab-actions">${button('Again','vocab-rate',`data-rating="again" data-id="${w.id}" ${!flipped?'disabled':''}`)}${button('Got it','vocab-rate',`data-rating="good" data-id="${w.id}" ${!flipped?'disabled':''}`)}${button('Easy','vocab-rate',`data-rating="easy" data-id="${w.id}" ${!flipped?'disabled':''}`)}</div><div class="studio-toolbar">${button(settings().vocab[w.id]?.saved?'Unsave word':'Save word','vocab-save',`data-id="${w.id}"`)}${button('Next word','vocab-next')}</div></section><aside class="studio-panel"><h2>Remember it in context.</h2><p>Use the word in a sentence. Then explain how a nearby clue changes its meaning.</p><p class="small muted">These are original vocabulary study cards, not official SAT questions. Ratings do not affect SAT accuracy.</p></aside></div>`;
  const list=vocabMode==='roots'?ROOTS:VOCAB.filter(w=>vocabMode!=='saved'||settings().vocab[w.id]?.saved);
  return heading(vocabMode==='roots'?'Find the family resemblance.':'Your vocabulary shelf.','Search definitions and examples. Use roots as clues, then check the word’s full meaning.')+tabs+`<label class="studio-toolbar">Search<input type="search" id="vocab-search" value="${esc(query)}" placeholder="Word, root, or meaning"></label><div class="vocab-list">${list.filter(w=>JSON.stringify(w).toLowerCase().includes(query.toLowerCase())).map(w=>`<article class="studio-panel"><h3>${esc(w.word||w.root)}</h3><p>${esc(w.definition||w.meaning)}</p><p class="small muted">${esc(w.example||w.examples?.join(', '))}</p>${w.word?button(settings().vocab[w.id]?.saved?'Saved ✓':'Save','vocab-save',`data-id="${w.id}"`):''}</article>`).join('')||'<div class="studio-empty">No matching cards. Save a word while reviewing to keep it here.</div>'}</div>`;
 }
 function achievements(){const stats=activity(state()),lessonCount=Object.values(settings().lessons).filter(x=>x.completed).length,reviewCount=Object.values(settings().review).filter(x=>x.successes).length,badges=[['First steps',stats.xp>0,'Earn your first study XP'],['Five approaches',state().sessions.flatMap(s=>s.records).filter(isIndependent).length>=5,'Solve five new questions independently with valid approaches'],['Three-day rhythm',stats.streak>=3,'Study on three consecutive days'],['Rule collector',lessonCount>=5,'Complete five lesson checks'],['Repair work',reviewCount>=5,'Successfully rework five questions'],['Test checkpoint',settings().exams.some(e=>e.status==='complete'),'Complete an assessment'],['Word builder',Object.values(settings().vocab).filter(v=>v.repetitions>0).length>=20,'Review twenty words'],['Desmos week',Object.keys(settings().challenge).length>=7,'Complete the seven-day challenge']];const weeks=new Map();for(const e of stats.events){const date=localDate(new Date(e.at)),start=addDays(date,-((new Date(date+'T12:00:00Z').getUTCDay()+6)%7));weeks.set(start,(weeks.get(start)||0)+e.points);}return heading('Build a habit you can see.','Your own milestones and best study weeks. Every result here comes from your saved work.')+`<div class="studio-grid"><section class="studio-panel"><h2>${stats.xp} XP earned</h2><p>${stats.streak} day current streak · ${stats.weekXp} XP this week</p>${calendar()}<form id="weekly-goal-form"><label>Weekly XP goal<input type="number" name="goal" min="25" max="5000" step="25" value="${settings().weeklyGoal}" required></label><button class="secondary" type="submit">Update goal</button></form></section><section class="studio-panel"><h2>Your best weeks</h2><p class="small muted">Personal leaderboard stored in this browser.</p>${[...weeks].sort((a,b)=>b[1]-a[1]).slice(0,8).map(([date,xp],i)=>`<div class="studio-section-head"><span>${i+1}. Week of ${short(date)}</span><strong>${xp} XP</strong></div>`).join('')||'<p>Start a lesson or practice session to record your first week.</p>'}</section></div><div class="badge-grid">${badges.map(([name,earned,description])=>`<article class="badge ${earned?'earned':''}"><span aria-hidden="true">${earned?'✦':'○'}</span><h3>${name}</h3><p>${description}</p><small>${earned?'Earned':'In progress'}</small></article>`).join('')}</div>`;}
 function challenge(){return heading('Seven graphing moves. One week.','Original Desmos exercises you can revisit at your own pace.')+`<div class="today-lessons">${CHALLENGE.map(d=>`<article class="lesson-card"><small>Day ${d.day} · ${esc(d.skill)}</small><h3>${esc(d.title)}</h3><p>${esc(d.instruction)}</p><p class="equation">${esc(d.expression)}</p><a href="https://www.desmos.com/calculator" target="_blank" rel="noopener noreferrer">Open Desmos</a><details class="studio-help"><summary>Check the result</summary><p>${esc(d.expected)}</p></details><footer>${button(settings().challenge[d.day]?'Completed ✓':'I practiced this move','challenge-done',`data-day="${d.day}" ${settings().challenge[d.day]?'disabled':''}`)}</footer></article>`).join('')}</div>`;}
 function testCatalog(){
  const active=settings().exams.find(e=>['active','between','break'].includes(e.status)),finished=settings().exams.filter(e=>e.status==='complete');
  return heading('Practice the test-day rhythm.','Fresh official bank questions arranged into our own diagnostic and test simulations.')+`<section class="studio-panel"><form id="exam-create-form"><div class="routine-fields"><label>Session type<select name="kind"><option value="diagnostic">Skill diagnostic · 12 questions per selected section</option><option value="section">Section simulation · two modules</option><option value="full">Full SAT simulation · four modules</option></select></label><label>Section<select name="section"><option ${state().section==='Math'?'selected':''}>Math</option><option ${state().section==='Reading and Writing'?'selected':''}>Reading and Writing</option><option>Both</option></select></label><label>Practice timing<select name="multiplier"><option value="1">Standard</option><option value="1.5">1.5× time</option><option value="2">2× time</option></select></label></div><p class="small muted">Diagnostics are untimed. Section simulations use two 35-minute Math modules or two 32-minute Reading and Writing modules. A full simulation has 98 questions and a 10-minute section break. Full simulation includes both sections.</p><p class="small muted">Our module 2 routing uses 65% correct as a practice threshold. These assembled tests and their results are not College Board tests or calibrated SAT scores. <a href="https://satsuite.collegeboard.org/in-school-assessments/sat-school-day/structure" target="_blank" rel="noopener noreferrer">Official format</a></p><p id="exam-create-error" class="form-error" role="alert"></p>${active?button('Resume current assessment','exam-resume',`data-id="${active.id}"`,true)+' '+button('End and archive current assessment','exam-abandon',`data-id="${active.id}"`):'<button class="primary" type="submit">Create fresh assessment</button>'}</form></section><div class="test-grid">${finished.map(e=>`<article class="test-card"><small>${short(localDate(new Date(e.completedAt)))}</small><h3>${e.kind==='diagnostic'?'Skill diagnostic':e.kind==='full'?'Full SAT simulation':esc(e.section)+' simulation'}</h3><p>${e.modules.flatMap(m=>m.records).filter(r=>r.correct).length}/${e.modules.reduce((n,m)=>n+m.questionIds.length,0)} correct</p>${button('Review results','exam-resume',`data-id="${e.id}"`)}</article>`).join('')}</div>`;
 }
 function examView(){const e=settings().exams.find(x=>x.id===settings().activeExamId);if(!e)return testCatalog();const m=e.modules[e.moduleIndex];
  if(e.status==='complete')return examResults(e);
  if(e.status==='abandoned'){settings().activeExamId=null;return testCatalog();}
  if(e.status==='between'||e.status==='break')return heading(e.status==='break'?'Take a section break.':'Module complete.','Your answers are saved. Solutions open after the assessment is complete.')+`<section class="studio-panel"><h2>${e.modules[e.moduleIndex+1].section} · module ${e.modules[e.moduleIndex+1].number} next</h2>${e.status==='break'?'<p>Ten-minute break. You may end it early for this practice simulation.</p><output id="exam-clock" class="test-clock">'+clock(remainingSeconds(e))+'</output>':'<p>Module 2 will be selected from your first-module accuracy using this site’s practice routing.</p>'}${button('Start next module','exam-next-module','',true)}<a class="secondary" href="#learn">Return to dashboard</a></section>`;
  const q=bank().get(m.questionIds[e.index]);context.expose?.(q.id);const answer=m.answers[q.id]||'',choices=/^[A-D]$/.test(q.answer);
  return `<section class="test-player"><div class="test-toolbar"><div><h1>${e.kind==='diagnostic'?'Skill diagnostic':e.kind==='full'?'SAT simulation':esc(e.section)+' simulation'}</h1><p>${esc(m.section)} · module ${m.number} · question ${e.index+1} of ${m.questionIds.length}</p></div><output id="exam-clock" class="test-clock" aria-label="Assessment time remaining">${m.seconds?clock(remainingSeconds(e)):'Untimed'}</output>${button('Assessment catalog','exam-catalog')}</div><nav class="test-modules" aria-label="Questions in this module">${m.questionIds.map((id,i)=>`<button data-action="exam-jump" data-index="${i}" class="${i===e.index?'active':''} ${m.answers[id]?'answered':''}" aria-label="Question ${i+1}${m.flags.includes(id)?', marked for review':''}" ${i===e.index?'aria-current="step"':''}>${i+1}${m.flags.includes(id)?' ⚑':''}</button>`).join('')}</nav><article class="test-question studio-panel"><div class="studio-section-head"><strong>${esc(q.skill)}</strong>${button(m.flags.includes(q.id)?'Marked for review ⚑':'Mark for review','exam-flag')}</div><img class="bank-image" src="${q.image}" alt="Official ${esc(q.skill)} question ${esc(q.number)}, ID ${q.id}"><form id="exam-answer-form">${choices?`<fieldset class="test-choices"><legend>Select an answer</legend>${['A','B','C','D'].map(letter=>`<label><input type="radio" name="answer" value="${letter}" ${answer===letter?'checked':''}><span>${letter}</span></label>`).join('')}</fieldset>`:`<label>Your answer<input type="text" name="answer" value="${esc(answer)}" placeholder="Number, decimal, or fraction" autocomplete="off"></label>`}<div class="test-actions">${button('Previous','exam-prev',e.index===0?'disabled':'')}<button class="primary" type="submit">${e.index===m.questionIds.length-1?'Save answer':'Save and next'}</button>${button('Review & submit module','exam-module-review')}</div></form>${source(q)}</article><div class="practice-tools">${button('Calculator / graph','tool-graph')}${button('Scratchpad','tool-scratch')}${button('Formula reference','tool-reference')}</div><p class="small muted">${m.seconds?'The timer continues while this assessment is open or the browser is closed. Expiration submits the current module.':'Untimed diagnostic; answer without hints to make the result useful.'} Answer feedback opens after completion.</p></section>`;
 }
 function examResults(e){const records=e.modules.flatMap(m=>m.records);return heading('Turn this result into your next step.','Your skill diagnostic has updated the adaptive plan. Review the questions, then practice fresh examples.')+`<div class="studio-stats"><div class="studio-stat"><strong>${records.filter(r=>r.correct).length}/${records.length}</strong><small>Correct answers</small></div><div class="studio-stat"><strong>${percent(records.filter(r=>r.correct).length,records.length)}</strong><small>Raw accuracy</small></div><div class="studio-stat"><strong>${records.filter(r=>!r.answer).length}</strong><small>Unanswered</small></div></div><div class="summary-actions"><a class="primary" href="#home">Continue daily path</a><a class="secondary" href="#review">Correction queue</a>${button('Assessment catalog','exam-catalog')}</div><section class="studio-panel"><h2>Results by module</h2>${e.modules.map(m=>`<p>${esc(m.section)} module ${m.number}: ${m.records.filter(r=>r.correct).length}/${m.records.length} correct · ${m.route==='pending'?'mixed':m.route} route</p>`).join('')}<p class="small muted">No scaled SAT score is assigned. Setups were not collected during testing, so these results inform diagnostics and do not unlock independent setup mastery.</p></section><div class="test-review">${records.map((r,i)=>{const q=bank().get(r.questionId);return `<details class="studio-panel"><summary>${i+1}. ${esc(q.skill)} · ${r.correct?'Correct':'Review'} · ID ${q.id}</summary><img class="bank-image" src="${q.image}" alt="Official question ${q.id}"><p>Your answer: ${esc(r.answer||'Unanswered')} · Correct answer: <strong>${esc(q.answer)}</strong></p>${q.key?.rationale?`<p>${esc(q.key.rationale)}</p>`:''}${q.key?`<a href="${esc(q.key.url)}" target="_blank" rel="noopener noreferrer">Official worked solution</a>`:'<p class="small muted">Detailed official worked solution unavailable for this item.</p>'}${source(q)}${desmosQuestionButton(q)}${button(settings().saved.includes(q.id)?'Saved for review':'Save for review','save-question',`data-id="${q.id}"`)}</details>`;}).join('')}</div>`;}
 function clock(sec){if(sec===null)return'Untimed';return Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0');}
 function renderView(view){applyTheme();return ({learn:dashboard,lessons,review,analytics,vocab:()=> (context.returnToPath?.()||'')+vocabulary(),achievements,challenge,desmos:desmos.render,tests:()=> (context.returnToPath?.()||'')+examView()})[view]?.()||'';}
 function tools(q){return `<div class="practice-tools">${button(settings().saved.includes(q.id)?'Saved ✓':'Save','save-question',`data-id="${q.id}"`)}${desmosQuestionButton(q)}<details class="tools-menu" ${highlightMode?'open':''}><summary>Tools</summary><div class="tools-options">${button('Calculator / graph','tool-graph')}${button('Scratchpad','tool-scratch')}${button('Reference','tool-reference')}${button(highlightMode?'Stop highlighting':'Highlight question','tool-highlight')}${button('Clear marks','tool-clear-marks')}${/^[A-D]$/.test(q.answer)?button('Eliminate choices','tool-eliminate'):''}${button(settings().focus?'Exit focus':'Focus mode','focus-toggle')}</div></details></div>`;}

 function openTool(title,content){modal().innerHTML=`<div class="dialog-header"><h2>${title}</h2>${button('Close','close-modal')}</div>${content}`;modal().showModal();}
 function currentQuestion(){const exam=settings().exams.find(e=>e.id===settings().activeExamId&&e.status==='active');if(location.hash==='#tests'&&exam)return bank().get(exam.modules[exam.moduleIndex].questionIds[exam.index]);return context.currentQuestion();}
 function plot(){const svg=document.querySelector('#local-graph');if(!svg)return;const expr=graphInput.replace(/^\s*y\s*=\s*/,''),range=graphRange,size=500,scale=size/(2*range),points=[];let path='',previous=null;for(let i=0;i<=500;i++){const x=-range+i/500*2*range;try{const y=calculate(expr,{x});if(Math.abs(y)>range*3){previous=null;continue;}const sx=(x+range)*scale,sy=(range-y)*scale;path+=(previous&&Math.abs(previous-y)<range?' L':' M')+sx.toFixed(2)+' '+sy.toFixed(2);previous=y;if(i%50===0)points.push({x,y});}catch{previous=null;}}let grid='';for(let i=0;i<=10;i++){const p=i*50;grid+=`<path d="M${p} 0V500M0 ${p}H500" stroke="currentColor" opacity=".12"/>`;}svg.innerHTML=`${grid}<path d="M250 0V500M0 250H500" stroke="currentColor" opacity=".6"/><path d="${path}" fill="none" stroke="var(--teal)" stroke-width="3"/><text x="265" y="20" fill="currentColor">y</text><text x="480" y="240" fill="currentColor">x</text>`;document.querySelector('#graph-message').textContent=path?`x and y from −${range} to ${range}. Approximate plot; check exact coordinates algebraically.`:'Could not plot this expression. Use x, numbers, arithmetic, parentheses, and powers.';}
 function click(action,target){
  if(desmos.click(action,target))return true;
  const studio=settings();
  if(action==='theme-toggle'){studio.theme=studio.theme==='dark'?'light':'dark';save();render();return true;}
  if(action==='focus-toggle'){studio.focus=!studio.focus;save();render();return true;}
  if(action==='lesson-open'){lessonId=target.dataset.id;lessonFeedback='';lessonAttempts=0;lessonExposed=false;location.hash='lessons';render();window.scrollTo({top:0});return true;}
  if(action==='lesson-reveal'){const l=LESSONS.find(x=>x.id===lessonId);if(l){lessonExposed=true;lessonFeedback=`<p>Answer: <strong>${esc(l.check.answer)}</strong>.</p><p>${esc(l.check.explanation)}</p><p class="small muted">This is a worked lesson check, not fresh mastery evidence. Try the check again, then practice a different question.</p>`;render();}return true;}
  if(action==='lessons-back'){lessonId=null;query='';lessonAttempts=0;lessonExposed=false;render();return true;}
  if(['lesson-practice','review-fresh'].includes(action)){practiceSkill(target.dataset.skill);return true;}
  if(action==='review-lesson'){lessonId=LESSONS.find(l=>l.section===state().section&&l.skill===target.dataset.skill)?.id||null;lessonFeedback='';lessonAttempts=0;lessonExposed=false;location.hash='lessons';render();return true;}
  if(action==='review-open'){const item=reviews().find(r=>r.question.id===target.dataset.id);if(item?.record.bookmarkOnly){const paused=state().sessions.find(s=>!s.completed&&s.questionIds.includes(item.question.id));if(paused){state().activeId=paused.id;save();location.hash='practice';render();}else startPractice([item.question.id],'saved');return true;}reviewId=target.dataset.id;reviewFeedback=null;render();window.scrollTo({top:0});return true;}
  if(action==='review-back'){reviewId=null;reviewFeedback=null;render();return true;}
  if(action==='vocab-tab'){vocabMode=target.dataset.mode;query='';flipped=false;render();return true;}
  if(action==='vocab-flip'){flipped=!flipped;render();return true;}
  if(action==='vocab-next'){vocabIndex++;flipped=false;render();return true;}
  if(action==='vocab-rate'){rateVocabulary(studio,target.dataset.id,target.dataset.rating);vocabIndex=0;flipped=false;save();render();return true;}
  if(action==='vocab-save'){const id=target.dataset.id;studio.vocab[id]||={repetitions:0};studio.vocab[id].saved=!studio.vocab[id].saved;save();render();return true;}
  if(action==='save-question'){const id=target.dataset.id;if(!bank().has(id))return true;studio.saved=studio.saved.includes(id)?studio.saved.filter(x=>x!==id):[...studio.saved,id];save();render();return true;}
  if(action==='challenge-done'){const day=Number(target.dataset.day);if(CHALLENGE.some(d=>d.day===day)){studio.challenge[day]=localDate();award(studio,'challenge-'+day,20,'challenge');save();render();}return true;}
  if(action==='exam-resume'){studio.activeExamId=target.dataset.id;save();render();return true;}
  if(action==='exam-catalog'){studio.activeExamId=null;save();render();return true;}
  if(action==='exam-abandon'){openTool('Archive this assessment?',`<p>Completed module results are retained. Unanswered reserved questions become available again. This is not counted as a completed test.</p>${button('Archive assessment','exam-confirm-abandon',`data-id="${target.dataset.id}"`,true)}`);return true;}
  if(action==='exam-confirm-abandon'){const e=studio.exams.find(e=>e.id===target.dataset.id);if(e){if(e.status==='active'){const m=e.modules[e.moduleIndex],ids=m.questionIds.filter(id=>m.answers[id]);if(ids.length){const partial=ids.map(id=>{const q=bank().get(id);return {questionId:id,section:q.section,skill:q.skill,exactSkill:q.skill,difficulty:q.difficulty,answer:m.answers[id],correct:context.grade(q,m.answers[id]),setup:'',setupCorrect:null,setupAssessment:'exam_answer_only',hintsUsed:0,revealed:false,submittedAt:new Date().toISOString()};});state().sessions.push({id:e.id+'-partial-'+e.moduleIndex,section:m.section,type:'assessment',questionIds:ids,index:ids.length-1,records:partial,drafts:{},completed:true,timed:m.seconds>0,createdAt:e.createdAt,completedAt:new Date().toISOString()});}}e.status='abandoned';for(const [i,m] of e.modules.entries())if(m.completedAt&&!state().sessions.some(s=>s.id===e.id+'-module-'+i))state().sessions.push({id:e.id+'-module-'+i,section:m.section,type:'assessment',questionIds:m.questionIds,index:m.questionIds.length-1,records:m.records,drafts:{},timed:m.seconds>0,completed:true,createdAt:e.createdAt,completedAt:m.completedAt});}studio.activeExamId=null;save();modal().close();render();return true;}
  if(action.startsWith('exam-')){tick();const e=studio.exams.find(e=>e.id===studio.activeExamId);if(!e)return true;const m=e.modules[e.moduleIndex];
   if(action==='exam-jump'){e.index=Math.max(0,Math.min(m.questionIds.length-1,Number(target.dataset.index)));save();render();}
   if(action==='exam-prev'){e.index=Math.max(0,e.index-1);save();render();}
   if(action==='exam-flag'){const id=m.questionIds[e.index];m.flags=m.flags.includes(id)?m.flags.filter(x=>x!==id):[...m.flags,id];save();render();}
   if(action==='exam-module-review'){const blank=m.questionIds.filter(id=>!m.answers[id]).length;openTool('Submit this module?',`<p>${Object.keys(m.answers).filter(id=>m.answers[id]).length}/${m.questionIds.length} answered · ${blank} unanswered · ${m.flags.length} marked for review.</p><p>You can revisit questions in this module before submitting. Submission locks the module.</p>${button('Submit module','exam-submit-module','',true)}`);}
   if(action==='exam-submit-module'){submitExamModule(e,data().questions);finishExam(state(),e);save();modal().close();render();window.scrollTo({top:0});}
   if(action==='exam-next-module'){try{startNextModule(e,data().questions,taken());save();render();}catch(error){toast(error.message);}}
   return true;
  }
  if(action==='score-add'){openTool('Add a score checkpoint',`<form id="score-form"><div class="routine-fields"><label>Source<select name="label"><option>Official SAT</option><option>Bluebook practice</option><option>Other diagnostic</option></select></label><label>Test date<input type="date" name="date" max="${localDate()}" required></label><label>Math score<input type="number" name="math" min="200" max="800" step="10" required></label><label>Reading and Writing score<input type="number" name="readingWriting" min="200" max="800" step="10" required></label></div><button class="primary" type="submit">Save checkpoint</button><p class="small muted">Self-reported scores; no automatic report parsing or verification.</p></form>`);return true;}
  if(action==='tool-graph'){openTool('Calculator and graph',`<form id="calculator-form"><label>Arithmetic expression<input name="expression" type="text" placeholder="800(0.8)^2" required></label><button class="secondary" type="submit">Calculate</button><output id="calculator-result" role="status"></output></form><form id="graph-form"><label>y =<input name="expression" type="text" value="${esc(graphInput)}" required></label><label>Visible range<select name="range">${[5,10,20,50].map(n=>`<option ${n===graphRange?'selected':''}>${n}</option>`).join('')}</select></label><button class="secondary" type="submit">Plot graph</button></form><svg id="local-graph" class="local-graph" viewBox="0 0 500 500" role="img" aria-label="Graph of your expression"></svg><p id="graph-message" class="small muted"></p><p class="small muted">Supports x, arithmetic, parentheses, and powers. For advanced functions, systems, and exact intersections, <a href="https://www.desmos.com/calculator" target="_blank" rel="noopener noreferrer">open Desmos</a>.</p>`);plot();return true;}
  if(action==='tool-scratch'){const q=currentQuestion();openTool('Scratchpad',`<p class="small muted">Notes save in this browser${q?' for question '+q.id:''}. They do not change answer or hint status.</p><label>Work and notes<textarea id="question-scratch" data-id="${q?.id||'general'}" rows="12">${esc(studio.notes[q?.id||'general']||'')}</textarea></label>`);return true;}
  if(action==='tool-reference'){openTool('Math reference',`<div class="lesson-detail"><h3>Geometry</h3><p>Circle: A = πr², circumference = 2πr. Triangle: A = bh/2. Rectangle: A = lw. Rectangular prism: V = lwh. Cylinder: V = πr²h. Sphere: V = 4πr³/3. Cone: V = πr²h/3. Pyramid: V = lwh/3.</p><h3>Triangles and angles</h3><p>a² + b² = c² for a right triangle. 45–45–90 sides: x, x, x√2. 30–60–90 sides: x, x√3, 2x. Triangle angles sum to 180°. A full circle is 360° or 2π radians.</p><h3>Modeling reminders</h3><p>Fixed cost + rate × units = total. Percentage increase: original × (1 + r). Percentage decrease: original × (1 − r). Successive changes multiply their factors. x-intercept: y = 0. y-intercept: x = 0.</p><p class="small muted">Study reference authored for Apple SAT; not a copy of an official test reference screen.</p></div>`);return true;}
  if(action==='tool-highlight'){highlightMode=!highlightMode;render();return true;}
  if(action==='tool-clear-marks'){const q=currentQuestion();if(q){studio.annotations[q.id]=[];studio.eliminated[q.id]=[];save();render();}return true;}
  if(action==='tool-eliminate'){document.querySelector('.choices')?.classList.toggle('elimination-mode');toast('Elimination mode: click a choice’s text to cross it out. Use the radio control to select an answer.');return true;}
  return false;
 }
 function submit(event){const form=event.target,fields=new FormData(form),studio=settings();
  if(form.id==='lesson-check-form'){event.preventDefault();const l=LESSONS.find(x=>x.id===lessonId);let correct=normalize(fields.get('answer'))===normalize(l.check.answer);try{correct ||= Math.abs(calculate(fields.get('answer'))-calculate(l.check.answer))<1e-6;}catch{}if(correct){studio.lessons[l.id]={completed:true,assisted:lessonAttempts>0||lessonExposed,at:new Date().toISOString()};award(studio,'lesson-'+l.id,25,'lesson');save();lessonFeedback=`<strong>Correct. Lesson reviewed.</strong><p>${esc(l.check.explanation)}</p><p class="small muted">${lessonAttempts>0||lessonExposed?'You used a retry or solution. This check is recorded as assisted lesson practice.':'This is one original tutorial check.'} Use a fresh bank question to test transfer; lesson completion does not establish skill mastery.</p>`;}else{lessonAttempts++;lessonFeedback=`<strong>Try the method again.</strong><p>A small hint: ${esc(l.steps[0])}</p>${button('Show worked answer','lesson-reveal')}`;}render();return true;}
  if(form.id==='review-form'){event.preventDefault();const q=bank().get(reviewId);try{const correct=context.grade(q,fields.get('answer')),next=recordReview(studio,q.id,{correct,setup:fields.get('setup'),rule:fields.get('rule'),errorType:fields.get('errorType'),hinted:fields.has('hinted')});reviewFeedback={correct,next};save();render();}catch(error){toast(error.message);}return true;}
  if(form.id==='weekly-goal-form'){event.preventDefault();const goal=Number(fields.get('goal'));if(goal>=25&&goal<=5000){studio.weeklyGoal=goal;save();render();}return true;}
  if(form.id==='exam-create-form'){event.preventDefault();try{if(studio.exams.some(e=>['active','between','break'].includes(e.status)))throw Error('Resume or archive the current assessment first.');const e=createExam(data().questions,taken(),{kind:fields.get('kind'),section:fields.get('section'),multiplier:Number(fields.get('multiplier')),id:crypto.randomUUID()});studio.exams.push(e);studio.activeExamId=e.id;save();render();window.scrollTo({top:0});}catch(error){document.querySelector('#exam-create-error').textContent=error.message;}return true;}
  if(form.id==='exam-answer-form'){event.preventDefault();const e=studio.exams.find(e=>e.id===studio.activeExamId),m=e.modules[e.moduleIndex];if(e.status!=='active')return true;if(remainingSeconds(e)===0){tick();return true;}m.answers[m.questionIds[e.index]]=String(fields.get('answer')||'').trim();if(e.index<m.questionIds.length-1)e.index++;save();render();window.scrollTo({top:0});return true;}
  if(form.id==='score-form'){event.preventDefault();const r={date:fields.get('date'),math:Number(fields.get('math')),readingWriting:Number(fields.get('readingWriting')),label:fields.get('label')};if(!validDate(r.date)||r.date>localDate()||[r.math,r.readingWriting].some(v=>v<200||v>800||v%10)){toast('Enter a valid past test date and section scores in steps of 10.');return true;}studio.scoreReports.push(r);studio.scoreReports.sort((a,b)=>b.date.localeCompare(a.date));save();modal().close();render();return true;}
  if(form.id==='calculator-form'){event.preventDefault();try{document.querySelector('#calculator-result').textContent=' = '+Number(calculate(fields.get('expression')).toPrecision(12));}catch(error){document.querySelector('#calculator-result').textContent=error.message;}return true;}
  if(form.id==='graph-form'){event.preventDefault();graphInput=String(fields.get('expression'));graphRange=Number(fields.get('range'));plot();return true;}
  return false;
 }
 function input(event){if(desmos.input(event))return true;const target=event.target;if(target.id==='question-scratch'){settings().notes[target.dataset.id]=target.value.slice(0,12000);save();return true;}if(target.id==='lesson-search'||target.id==='vocab-search'){const pos=target.selectionStart,id=target.id;query=target.value;render();const next=document.getElementById(id);next?.focus();next?.setSelectionRange(pos,pos);return true;}if(target.closest('#exam-answer-form')){const e=settings().exams.find(e=>e.id===settings().activeExamId);if(e?.status==='active'&&remainingSeconds(e)!==0){e.modules[e.moduleIndex].answers[e.modules[e.moduleIndex].questionIds[e.index]]=String(new FormData(target.closest('form')).get('answer')||'');save();}return true;}return false;}
 function tick(){const e=settings().exams.find(e=>e.id===settings().activeExamId);if(!e||!['active','break'].includes(e.status))return;const sec=remainingSeconds(e),el=document.querySelector('#exam-clock');if(el)el.textContent=clock(sec);if(e.status==='active'&&sec===0){submitExamModule(e,data().questions);finishExam(state(),e);save();if(location.hash==='#tests')render();toast('Time ended. This module was submitted.');}}
 function eliminate(choice){const q=currentQuestion();if(!q)return;const letter=choice.querySelector('input')?.value;if(!letter)return;const list=settings().eliminated[q.id]||[];settings().eliminated[q.id]=list.includes(letter)?list.filter(x=>x!==letter):[...list,letter];save();}
 function afterRender(){
  const q=currentQuestion();if(!q||location.hash==='#tests')return;
  for(const choice of document.querySelectorAll('.choice'))if(settings().eliminated[q.id]?.includes(choice.querySelector('input')?.value))choice.classList.add('crossed-out');
  const content=document.querySelector('.question-body .question-text')||document.querySelector('.question-body .bank-image');if(!content)return;
  const wrapper=document.createElement('div');wrapper.className='annotated-question';content.replaceWith(wrapper);wrapper.append(content);
  const overlay=document.createElement('div');overlay.className='annotation-overlay'+(highlightMode?' drawing':'');overlay.setAttribute('aria-label','Drag to highlight the question');
  const marks=settings().annotations[q.id]||[];overlay.innerHTML=marks.map(m=>`<span style="left:${Number(m.x)||0}%;top:${Number(m.y)||0}%;width:${Number(m.w)||0}%;height:${Number(m.h)||0}%"></span>`).join('');wrapper.append(overlay);
  let origin=null;overlay.addEventListener('pointerdown',event=>{if(!highlightMode)return;const rect=overlay.getBoundingClientRect();origin={x:(event.clientX-rect.left)/rect.width*100,y:(event.clientY-rect.top)/rect.height*100};overlay.setPointerCapture(event.pointerId);});
  overlay.addEventListener('pointerup',event=>{if(!origin)return;const rect=overlay.getBoundingClientRect(),x=Math.max(0,Math.min(100,(event.clientX-rect.left)/rect.width*100)),y=Math.max(0,Math.min(100,(event.clientY-rect.top)/rect.height*100)),mark={x:Math.min(x,origin.x),y:Math.min(y,origin.y),w:Math.abs(x-origin.x),h:Math.abs(y-origin.y)};origin=null;if(mark.w<1||mark.h<1)return;settings().annotations[q.id]=[...marks,mark].slice(-100);save();render();});
 }
 return {render:renderView,click,submit,input,tools,tick,applyTheme,afterRender,eliminate,sectionChanged:()=>{lessonId=null;lessonFeedback='';lessonAttempts=0;lessonExposed=false;query='';reviewId=null;reviewFeedback=null;}};
}
